  function startBoxDrag(e){if(e.target.closest('.welog-layout-resize,[data-crop-edge]'))return;if(!selected||cropMode)return;startDrag(e,selected)}
  function startResize(e){if(!editing||!selected||cropMode)return;e.preventDefault();e.stopImmediatePropagation();var s=read()[selected],map=targets(sheet),r=visualRect(selected,map[selected]),sc=localScale();gesture={type:'resize',key:selected,clientX:e.clientX,clientY:e.clientY,scale:s.scale,startW:Math.max(20,(r?r.right-r.left:100)/sc.x)};document.body.classList.add('welog-layout-dragging');window.addEventListener('pointermove',onMove,true);window.addEventListener('pointerup',endGesture,true)}
  function startCrop(e){if(!editing||selected!=='center'||!cropMode)return;e.preventDefault();e.stopImmediatePropagation();var edge=e.currentTarget.dataset.cropEdge,s=read().center,c=cleanCrop(s.crop),full=unionRect(targets(sheet).center),sc=localScale();gesture={type:'crop',key:'center',edge:edge,clientX:e.clientX,clientY:e.clientY,crop:c,fullW:Math.max(40,(full.right-full.left)/sc.x),fullH:Math.max(40,(full.bottom-full.top)/sc.y)};document.body.classList.add('welog-layout-dragging');window.addEventListener('pointermove',onMove,true);window.addEventListener('pointerup',endGesture,true)}
