  function endGesture(){if(!gesture)return;gesture=null;document.body.classList.remove('welog-layout-dragging');window.removeEventListener('pointermove',onMove,true);window.removeEventListener('pointerup',endGesture,true);scheduleFit();drawOverlay()}
  function fitCard(){if(!sheet)return;clearTimeout(fitTimer);sheet.style.setProperty('--welog-safe-x','0px');sheet.style.setProperty('--welog-safe-top','0px');sheet.style.setProperty('--welog-safe-bottom','0px');requestAnimationFrame(function(){var sr=sheet.getBoundingClientRect(),map=targets(sheet),all=[];Object.keys(map).forEach(function(k){var r=visualRect(k,map[k]);if(r&&r.right>r.left&&r.bottom>r.top)all.push(r)});if(!all.length)return;var margin=22,left=Math.min.apply(null,all.map(function(r){return r.left})),right=Math.max.apply(null,all.map(function(r){return r.right})),top=Math.min.apply(null,all.map(function(r){return r.top})),bottom=Math.max.apply(null,all.map(function(r){return r.bottom}));var needL=Math.max(0,Math.ceil(sr.left+margin-left)),needR=Math.max(0,Math.ceil(right-(sr.right-margin))),needT=Math.max(0,Math.ceil(sr.top+margin-top)),needB=Math.max(0,Math.ceil(bottom-(sr.bottom-margin)));var safeX=Math.max(needL,needR);sheet.style.setProperty('--welog-safe-x',safeX+'px');sheet.style.setProperty('--welog-safe-top',needT+'px');sheet.style.setProperty('--welog-safe-bottom',needB+'px');requestAnimationFrame(function(){if(editing)drawOverlay()})})}
