  function ensureToolCard(){if(!controls)return;var anchor=controls.querySelector('.layout-ratio-controls');var old=controls.querySelector('.welog-section-layout-control');if(old)old.remove();if(!anchor){if(editing)exitEditor();return}var box=controls.querySelector('.welog-direct-layout-control');if(!box){box=document.createElement('section');box.className='welog-direct-layout-control';box.innerHTML='<div class="welog-direct-head"><div><b>편집 툴</b><span>시트에서 파트를 직접 클릭해 이동·크기 조절합니다.</span></div><button type="button" data-layout-open>편집 툴 열기</button></div><p>페어명 · A+B 세트 · 중앙 그림 · OK 표시 · 커미션 출처를 직접 조정할 수 있습니다. 중앙 그림은 선택 후 영역 자르기도 가능합니다.</p>';anchor.insertAdjacentElement('afterend',box)}var b=box.querySelector('[data-layout-open]');b.textContent=editing?'편집 툴 닫기':'편집 툴 열기';b.classList.toggle('on',editing)}
  function ensureEditorHud(){var hud=document.querySelector('.welog-layout-hud');if(hud)return hud;hud=document.createElement('div');hud.className='welog-layout-hud';hud.innerHTML='<div><b>레이아웃 편집</b><span>파트를 드래그해 이동 · 모서리 핸들로 크기 조절 · 중앙 그림은 영역 자르기</span></div><div class="welog-layout-hud-actions"><button type="button" data-layout-crop hidden>영역 자르기</button><button type="button" data-layout-crop-reset hidden>자르기 초기화</button><button type="button" data-layout-reset>기본 정렬</button><button type="button" data-layout-done>완료</button></div>';document.body.appendChild(hud);hud.querySelector('[data-layout-reset]').onclick=resetLayout;hud.querySelector('[data-layout-done]').onclick=exitEditor;hud.querySelector('[data-layout-crop]').onclick=function(){if(selected!=='center')return;cropMode=!cropMode;drawOverlay()};hud.querySelector('[data-layout-crop-reset]').onclick=resetCrop;return hud}
